//! `keep_range` (it keeps a range of the DOCUMENT's timeline, and is
//! applied only to a derived document, spec §11 CJ-50).
//! Everything else — all fifty-six — works
//! inside a nest as it works on the timeline, `nest` and `unnest`
//! included.
//!
            .and_then(|id| u32::try_from(id).ok())
            .map(Some)
            .ok_or_else(|| format!("scope must be a nest id, not {}", describe(found))),
    }
}

/// The ops with no meaning inside a nest, by name, or `None` for the
/// fifty-six that work in there unchanged.
///
/// Exhaustive rather than a short list with a `_` arm, and that is the
/// point of writing it out: an op added by a later phase does not compile
/// until somebody has decided which side of this line it falls on. The
/// compiler is the reviewer.
fn refused_inside(op: &Op) -> Option<&'static str> {
    match op {
        // A nest has no `markers[]` (spec §5.2). The timeline's markers are
        // PROJECT time and chapter points on the exported file; a marker
        // measured from a nest's own zero would be neither.
        Op::AddMarker { .. } => Some("add_marker"),
        Op::SetMarker { .. } => Some("set_marker"),
        Op::RemoveMarker { .. } => Some("remove_marker"),

        // Half of a canvas is not a nest's to have — the rate, the
        // background and the two switches are the document's — and the half
        // that is, its size, is FROZEN at the size the parent had when the
        // nest was made, so that a later `set_canvas` cannot silently
        // re-lay-out content nobody touched ([`Nest`]). Honouring that here
        // would be `set_canvas` reaching through a scope to do the one
        // thing the freeze exists to stop.
        Op::SetCanvas { .. } => Some("set_canvas"),

        // A nest references the parent's `media[]` in the parent's one id
        // space (spec §5.2). So a media edit inside a scope is a media edit
        // on the document wearing a scope — the same act, spelled twice —
        // and `remove_media` is worse than redundant: it would strip the
        // clips that show the file from the view's containers and leave
        // every TIMELINE clip that shows it dangling, since those are not
        // in the view to be found.
        Op::AddMedia { .. } => Some("add_media"),
        Op::RelinkMedia { .. } => Some("relink_media"),
        Op::RemoveMedia { .. } => Some("remove_media"),
        Op::SetMediaColor { .. } => Some("set_media_color"),
        Op::SetMediaSpeech { .. } => Some("set_media_speech"),
        Op::SetMediaCursor { .. } => Some("set_media_cursor"),

        // An adjustment clip grades what is behind it at the top level only
        // (spec §11 GR-6): `check_clips` refuses one inside a nest, so the
        // op is refused here before a view is built.
        Op::AddAdjustmentClip { .. } => Some("add_adjustment_clip"),

        // A range kept as a whole project is the DOCUMENT's timeline, edited
        }

        let earliest = selected.iter().map(|c| c.start).min().unwrap_or(0);
        let latest = selected.iter().map(clip_end).max().unwrap_or(0);
        if latest <= earliest {
            return Ok(Outcome::Identity);
        }

        // The source tracks, back-most first, so the nest's own stack keeps
        // the order the timeline had. `track_index` is the stack position;
        // a clip on a track that is not in `tracks` cannot exist (`validate`
        // refuses it) and is skipped rather than defended against twice.
        let mut sources: Vec<(usize, u32)> = Vec::new();
        for clip in &selected {
            if let Some(index) = self.track_index(clip.track) {
                if !sources.iter().any(|(_, id)| *id == clip.track) {
                    sources.push((index, clip.track));
                }
            }
        }
        sources.sort_unstable();
        // The front-most source track that is not a matte track is where
        // the nest clip goes (MT-5): a matte pair nested together must land
        // where its picture was drawn, not on the matte track, where the
        // whole nest would become a matte. The front-most when all are. The
        // nest's own tracks count toward `MAX_TRACKS` like any other
        // (`format::check_caps`), so a selection that would overrun the cap
        // is caught by `finish` rather than counted twice here.
        let drawn = sources
            .iter()
            .rev()
            .find(|(_, id)| self.track(*id).is_some_and(|t| t.matte.is_none()));
        let Some((_, front_track)) = drawn.or(sources.last()).copied() else {
            return Ok(Outcome::Identity);
        };

        let mut next = self.clone();
        let nest_id = next.allocate_id();
        let mut tracks: Vec<Track> = Vec::with_capacity(sources.len());
        let mut mapping: Vec<(u32, u32)> = Vec::with_capacity(sources.len());
        for (_, id) in &sources {
            let Some(source) = self.track(*id) else {
                continue;
            };
            let track = nested_track(&mut next, source, *id != front_track);
            mapping.push((*id, track.id));
            tracks.push(track);
        }
        // The carry rule (MT-5), one pass over the mapping: a nested track
        // stays a matte only when the nested track directly behind it is the
        // copy of its source's target. A matte nested without its target
        // draws inside the nest as an ordinary track (owner, O9).
        for index in 0..tracks.len() {
            let from = mapping.get(index).map(|(from, _)| *from);
            let behind = index
                .checked_sub(1)
                .and_then(|i| mapping.get(i))
                .map(|(from, _)| *from);
            let carried = from.and_then(|from| matte_target(&self.tracks, from));
            if carried.is_none() || carried != behind {
                if let Some(track) = tracks.get_mut(index) {
                    track.matte = crate::model::TrackMatte::None;
                }
            }
        }

        // The clips move WHOLE — ids, actions, transitions and all — so
        // nothing about them has to be re-minted or re-checked. Only their
