        Source::Media {
            media: id,
            r#in,
            reversed,
        } => Source::Media {
            media: mapped(id),
            r#in: (*r#in).max(0),
            reversed: *reversed,
        },
        Source::Still { media: id, at } => Source::Still {
            media: mapped(id),
            at: (*at).max(0),
        },
        Source::Image { media: id } => Source::Image { media: mapped(id) },
        Source::Nest { project } => Source::Nest {
            project: nests.get(project).copied().unwrap_or(*project),
        },
        other => other.clone(),
